    [138] = {
      beijing = 2138,
      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "I only now thought in hindsight of the close proximity we kept while swimming and also of what he had said with a laugh at the dinner table.",
      next = {139}
    },
    [139] = {
      beijing = 2138,
      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "Everything that seemed so spur-of-the-moment to me was actually something he'd been waiting on for some time.",
      next = {140}
    },
    [140] = {
      beijing = 2138,
      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "Finally, I thought of how he'd been looking at me underwater when I turned my head, and that sudden kiss on the ocean floor seemed to tell me the answer.",
      next = {141}
    },
    [141] = {
      beijing = 2138,
      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "Now that the person he'd longed for was here, even just a meal or an exchanged glance was enough to make him happy.",
      next = {142}
    },
    [142] = {
      beijing = 2138,
      dialog = 3,
      music = "1002_2023spring",
      renwu = "npc",
      sentence = "But how could Victor—someone so used to keeping a firm grip on the initiative and thereby mitigating risk—also be the best person in the world at sitting back and waiting?",
      next = {143}
    },
    [143] = {
      beijing = 2138,
