      music = "1002_2023spring",
      renwu = "npc",
      role1 = 105000,
      role2 = 102101,
      role3 = 102203,
      role5 = 105402,
      roleanim = 1.2,
      sentence = "My heart melted all at once, and I gave in to the urge to kiss him again.",
      next = {144}
