  [620081] = {
    [1] = {
      beijing = 1712,
      dialog = 3,
      music = "03_Daily",
      renwu = "npc",
      sentence = "凌晨两点的书房里，我和许墨逐渐被堆起来的资料淹没。",
      next = {2}
    },
    [2] = {
      beijing = 1712,
      dialog = 3,
      music = "03_Daily",
      renwu = "npc",
      sentence = "最近，公司以恋语市为背景做了一档城市环保短片，谁知道竟与另一鸟类科学节目“杠”上了。",
      next = {3}
    },
    [3] = {
      beijing = 1712,
      dialog = 3,
      music = "03_Daily",
      renwu = "npc",
      sentence = "短片以野生动物保护协会提供的资料为基础，提到了一种年年都会到恋语市栖息的濒危候鸟——黑脸琵鹭。",
      next = {4}
    },
    [4] = {
      beijing = 1712,
      dialog = 3,
      music = "03_Daily",
      renwu = "npc",
      sentence = "但另一档同期播出的科学节目公布黑脸琵鹭在国内的大小栖息地时，却没有只言片语提及恋语市。",
      next = {5}
    },
    [5] = {
      beijing = 1712,
      dialog = 3,
      music = "03_Daily",
      renwu = "npc",
      sentence = "两方结论相悖，吃瓜网友都在等双方回应。第一时间下架短片后，我便拉着许墨一起求证。",
      next = {6}
    },
    [6] = {
      beijing = 1712,
      dhead = 305,
      dialog = 1,
      music = "03_Daily",
      renming = "$u",
      renwu = "npc",
      sentence = "对方节目说他们的资料来自黑脸琵鹭全球论坛……这个来源的确算得上权威。",
      next = {7}
    },
    [7] = {
      beijing = 1712,
      dhead = 305,
      dialog = 1,
      music = "03_Daily",
      renming = "$u",
      renwu = "npc",
      sentence = "不过它更关注的是繁育地里的种群数量，对沿途栖息地的情况更新不太及时。",
      next = {8}
    },
    [8] = {
      beijing = 1712,
      dhead = 306,
      dialog = 1,
      music = "03_Daily",
      renming = "$u",
      renwu = "npc",
      sentence = "所以我们当时没有采用。",
      next = {9}
