      dhead = 304,
      dialog = 1,
      music = "03_Daily",
      renming = "$u",
      renwu = "npc",
      sentence = "没想到阴差阳错，还是被卷进了乌龙里……",
      next = {10}
    },
    [10] = {
      beijing = 1712,
      dialog = 3,
      music = "03_Daily",
      renwu = "npc",
      sentence = "我有气无力地趴在成堆的资料上，长长哀叹一声。",
      next = {11}
    },
    [11] = {
      beijing = 1712,
      dialog = 3,
      idx = 2,
      music = "03_Daily",
      renwu = "npc",
      role1 = 2144000,
      role2 = 202103,
      role3 = 202201,
      ruchang = -1,
      sentence = "许墨被我夸张的举动逗得轻轻一笑，大手覆盖上我的头顶揉了揉。",
      next = {12}
    },
    [12] = {
      beijing = 1712,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "03_Daily",
      renming = "许墨",
      renwu = "npc",
      role1 = 2144000,
      role2 = 202101,
      role3 = 202201,
      sentence = "$u不用自责。或许黑脸琵鹭也因为这次争端，被更多人关注。毕竟舆论向来是把双刃剑。",
      voice = 1,
