      music = "03_Daily",
      renwu = "npc",
      role1 = 2144000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "我难免沮丧地噘起了嘴，伸手勾住了许墨的手指。他笑了一声，弯下腰与我对上视线。",
      next = {16}
    },
    [16] = {
