      dialog = 2,
      idx = 2,
      male = 2,
      music = "03_Daily",
      renming = "许墨",
      renwu = "npc",
      role1 = 2144000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "大家很喜欢你的故事，所以我想，比起去追究对错，他们更期待的是你能补上故事的瑕疵。",
      voice = 1,
      next = {17}
