      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "This news caused a huge disturbance, and comments of sadness and despair surged from the public. I turned off my phone, unable to avoid feeling weighed down by all the negative emotions too.",
