    [5] = {
      beijing = 1363,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "Not far away, an STF Agent returned from a mission leaned wearily against a wall and slept. Gavin had been busy too from the previous night all the way until now.",
