    [7] = {
      beijing = 1363,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "Gavin drank the water down in one gulp, and the weary look in his brow seemed to ease up, but first he looked to see how I was doing.",
      next = {8}
    },
    [8] = {
      beijing = 1363,
      dialog = 2,
      idx = 4,
      music = "30_WarmSnow",
      renming = "Gavin",
