      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 450000,
      role2 = 403111,
      role3 = 403203,
      role5 = 450401,
      sentence = "I'm alright... Gavin, if the comet cluster hits the Earth, won't everything just get destroyed in an instant?",
