      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 450000,
      role2 = 403111,
      role3 = 403203,
      role5 = 450401,
      sentence = "A look of understanding flashed in Gavin's eyes, and he didn't not evade the question.",
      next = {11}
    },
